function sparkline(svg,data){
  const w=120,ht=26,p=2,mx=Math.max(...data),mn=Math.min(...data);
  const X=i=>p+i*(w-2*p)/(data.length-1), Y=v=>ht-p-(v-mn)/((mx-mn)||1)*(ht-2*p);
  let d='';data.forEach((v,i)=>d+=(i?'L':'M')+X(i).toFixed(1)+' '+Y(v).toFixed(1));
  svg.appendChild(el('path',{d:d+`L${X(data.length-1)} ${ht} L${X(0)} ${ht} Z`,fill:'var(--accent)','fill-opacity':'.10'}));
  svg.appendChild(el('path',{d,fill:'none',stroke:'var(--accent)','stroke-width':'1.5','stroke-linejoin':'round','stroke-linecap':'round'}));
  svg.appendChild(el('circle',{cx:X(data.length-1),cy:Y(data[data.length-1]),r:'2',fill:'var(--accent)'}));
}

