/* ---------- vertical bars ---------- */
function vbars(svg,data,{W,H,labels,color='var(--accent)',fmtx}){
  const pl=32,pr=8,pt=12,pb=24,iw=W-pl-pr,ih=H-pt-pb,n=data.length;
  const mx=Math.max(...data),yt=niceMax(mx);
  const bw=iw/n*0.62, gap=iw/n;
  const Y=v=>pt+ih-v/yt*ih;
  [0,yt/2,yt].forEach(g=>{const y=Y(g);svg.appendChild(el('line',{class:'glin',x1:pl,y1:y,x2:W-pr,y2:y}));
    svg.appendChild(el('text',{class:'axlab',x:pl-6,y:y+3,'text-anchor':'end'},''+Math.round(g)));});
  data.forEach((v,i)=>{const x=pl+i*gap+(gap-bw)/2,y=Y(v),hgt=pt+ih-y;
    const r=el('rect',{x:x.toFixed(1),y:y.toFixed(1),width:bw.toFixed(1),height:Math.max(0,hgt).toFixed(1),rx:'3',fill:color,'fill-opacity':'.9'});
    r.style.cursor='default';
    r.addEventListener('mouseenter',e=>{r.setAttribute('fill-opacity','1');showTip(e.clientX,e.clientY,`<div class="tt">${labels[i]}</div><div class="tv tnum">${fmt(v)} <small>条</small></div>`);});
    r.addEventListener('mousemove',e=>showTip(e.clientX,e.clientY,`<div class="tt">${labels[i]}</div><div class="tv tnum">${fmt(v)} <small>条</small></div>`));
    r.addEventListener('mouseleave',()=>{r.setAttribute('fill-opacity','.9');hideTip();});
    svg.appendChild(r);
    if(fmtx&&fmtx(i)!==null)svg.appendChild(el('text',{class:'axlab',x:pl+i*gap+gap/2,y:H-9,'text-anchor':'middle'},fmtx(i)));
  });
}
vbars($('#barHour'),D.by_hour,{W:560,H:220,labels:D.by_hour.map((_,i)=>i+':00'),fmtx:i=>i%3===0?i:null});
vbars($('#barWeek'),D.weekday_totals,{W:340,H:220,color:'var(--s5)',labels:WD,fmtx:i=>WD[i].slice(1)});
