/* ---------- heatmap ---------- */
(function(){
  const heat=$('#heat');const flat=D.heatmap.flat();const mx=Math.max(...flat);
  const seq=['--seq0','--seq1','--seq2','--seq3','--seq4','--seq5','--seq6','--seq7'];
  const col=v=>{if(v===0)return 'var(--surface-2)';const t=v/mx;const idx=Math.min(seq.length-1,1+Math.floor(t*(seq.length-1)));return 'var('+seq[idx]+')';};
  heat.appendChild(h('div',{class:'hx'},''));
  for(let hh=0;hh<24;hh++)heat.appendChild(h('div',{class:'hx'},hh%3===0?(''+hh):''));
  D.heatmap.forEach((row,d)=>{
    heat.appendChild(h('div',{class:'hl'},WD[d]));
    row.forEach((v,hh)=>{const c=h('div',{class:'hc'});c.style.background=col(v);
      c.addEventListener('mouseenter',e=>showTip(e.clientX,e.clientY,`<div class="tt">${WD[d]} · ${hh}:00–${hh}:59</div><div class="tv tnum">${v} <small>条</small></div>`));
      c.addEventListener('mousemove',e=>showTip(e.clientX,e.clientY,`<div class="tt">${WD[d]} · ${hh}:00–${hh}:59</div><div class="tv tnum">${v} <small>条</small></div>`));
      c.addEventListener('mouseleave',hideTip);heat.appendChild(c);});
  });
  const leg=$('#heatLeg');leg.appendChild(h('span',{class:'lg'},'少'));
  [1,3,5,7].forEach(n=>{const i=h('i');i.style.background='var('+seq[n]+')';leg.appendChild(h('span',{class:'lg'},[i]));});
  leg.appendChild(h('span',{class:'lg'},'多'));
})();

/* ---------- bar-in-cell list ---------- */
function rankList(node,items,{max,fmtVal,rankNo=true,barColor='var(--accent-wash)'}){
  const mx=max||Math.max(...items.map(i=>i.v));
  items.forEach((it,idx)=>{
    const row=h('div',{class:'row'});
    const bar=h('div',{class:'bar'});bar.style.width=(it.v/mx*100)+'%';if(it.barColor)bar.style.background=it.barColor;else bar.style.background=barColor;
    row.appendChild(bar);
    const nm=h('div',{class:'nm'});
    if(rankNo)nm.appendChild(h('span',{class:'rk'},''+(idx+1)));
    nm.appendChild(h('span',{},it.name));
    if(it.chip)nm.appendChild(h('span',{class:'chip '+(it.chipClass||'')},it.chip));
    row.appendChild(nm);
    row.appendChild(h('div',{class:'v',html:fmtVal(it)}));
    node.appendChild(row);
  });
}

