function ring(part){const r=26,c=2*Math.PI*r,off=c*(1-(part||0));
  return `<svg class="ring" viewBox="0 0 66 66"><circle cx="33" cy="33" r="${r}" fill="none" stroke="var(--divider)" stroke-width="7"/>
    <circle cx="33" cy="33" r="${r}" fill="none" stroke="var(--accent)" stroke-width="7" stroke-linecap="round"
    stroke-dasharray="${c.toFixed(1)}" stroke-dashoffset="${off.toFixed(1)}" transform="rotate(-90 33 33)"/>
    <text x="33" y="37" text-anchor="middle" font-family="var(--font-mono)" font-size="14" font-weight="700" fill="var(--ink)">${part!=null?Math.round(part*100)+'%':'—'}</text></svg>`;}
