const opNode=$('#ops');
ops.forEach(o=>{const c=h('div',{class:'op '+o.cls});
  c.appendChild(h('div',{class:'oph'},[h('span',{class:'tag '+o.tagCls},o.tag),h('h4',{},o.title)]));
  c.appendChild(h('div',{class:'metric',html:o.metric}));
  c.appendChild(h('p',{},o.p));
  c.appendChild(h('div',{class:'act'},o.act));
  opNode.appendChild(c);});

/* ---------- leads table ---------- */
(function(){const t=$('#leads');const mx=Math.max(...D.leads.map(l=>l.inbound));
  t.appendChild(h('thead',{},h('tr',{},[h('th',{},'客户（化名）'),h('th',{},'主要意图'),h('th',{style:'width:34%'},'主动私信条数'),h('th',{},'活跃窗口')])));
  const tb=h('tbody',{});
  D.leads.forEach(l=>{
    const tr=h('tr',{});
    tr.appendChild(h('td',{},l.name));
    tr.appendChild(h('td',{},[h('span',{class:'chip op'},l.intent)]));
    const bc=h('td',{class:'barcell'});const b=h('div',{class:'b'});b.style.width=(l.inbound/mx*72)+'%';
    bc.appendChild(b);bc.appendChild(h('span',{class:'num tnum',style:'position:relative'},''+l.inbound));
    tr.appendChild(bc);
    tr.appendChild(h('td',{class:'win'},l.first.slice(5)+' → '+l.last.slice(5)));
    tb.appendChild(tr);
  });
  t.appendChild(tb);
})();

